// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= c.totalDistributed());
        address owner = address(this);
        c.XBornID();
        uint256 afterDistrib = c.totalDistributed();
        c.burn(burnAmount);
        uint256 afterBurn = c.totalDistributed();
        assertTrue(afterBurn == afterDistrib - burnAmount);
    }
}

